package com.example.inventoryservicefeb25.service;
import com.example.inventoryservicefeb25.model.*; import com.example.inventoryservicefeb25.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class InventoryService {private static final String PREFIX="inventory:stock:";private final InventoryRepository repository;private final RedisTemplate<String,Object> redis;private final Duration ttl;private final InventoryReservationRepository reservations; public InventoryService(InventoryRepository repository,RedisTemplate<String,Object> redis,InventoryReservationRepository reservations,@Value("${inventory.cache.ttl-seconds:300}")long ttlSeconds){this.repository=repository;this.redis=redis;this.reservations=reservations;this.ttl=Duration.ofSeconds(ttlSeconds);} public int getStock(Long productId){String k=PREFIX+productId;Object c=redis.opsForValue().get(k);if(c instanceof Integer i)return i;Inventory x=repository.findByProductId(productId).orElseThrow(()->new IllegalArgumentException("Inventory not initialized for product "+productId));redis.opsForValue().set(k,x.getAvailableQuantity(),ttl);return x.getAvailableQuantity();}
@Transactional public Inventory setStock(Long productId,int quantity){if(productId==null||quantity<0)throw new IllegalArgumentException("Invalid productId or quantity");Inventory x=repository.findByProductId(productId).orElseGet(Inventory::new);x.setProductId(productId);x.setAvailableQuantity(quantity);Inventory saved=repository.save(x);evict(productId);return saved;}
@Transactional public void reserve(Long productId,int quantity){if(quantity<=0)throw new IllegalArgumentException("Quantity must be positive");Inventory x=repository.findByProductIdForUpdate(productId).orElseThrow(()->new IllegalArgumentException("Inventory not initialized for product "+productId));if(x.getAvailableQuantity()<quantity)throw new IllegalStateException("Insufficient stock for product "+productId);x.setAvailableQuantity(x.getAvailableQuantity()-quantity);repository.save(x);evict(productId);}
@Transactional public void release(Long productId,int quantity){if(quantity<=0)throw new IllegalArgumentException("Quantity must be positive");Inventory x=repository.findByProductIdForUpdate(productId).orElseThrow();x.setAvailableQuantity(x.getAvailableQuantity()+quantity);repository.save(x);evict(productId);}
@Transactional public String reserveForOrder(Long orderId,Long productId,int quantity,long ttlSeconds){if(orderId==null||productId==null||quantity<=0)throw new IllegalArgumentException("Invalid reservation request");Optional<InventoryReservation> old=reservations.findByOrderIdAndProductId(orderId,productId);if(old.isPresent()){if(old.get().getStatus()==ReservationStatus.RESERVED)return old.get().getReservationId();throw new IllegalStateException("Reservation already completed");}Inventory x=repository.findByProductIdForUpdate(productId).orElseThrow();if(x.getAvailableQuantity()<quantity)throw new IllegalStateException("Insufficient stock for product "+productId);x.setAvailableQuantity(x.getAvailableQuantity()-quantity);repository.save(x);InventoryReservation rr=new InventoryReservation();rr.setReservationId(UUID.randomUUID().toString());rr.setOrderId(orderId);rr.setProductId(productId);rr.setQuantity(quantity);rr.setStatus(ReservationStatus.RESERVED);rr.setCreatedAt(Instant.now());rr.setExpiresAt(Instant.now().plusSeconds(ttlSeconds));reservations.save(rr);evict(productId);return rr.getReservationId();}
@Transactional public void releaseReservation(String reservationId){InventoryReservation rr=reservations.findByReservationIdForUpdate(reservationId).orElseThrow();if(rr.getStatus()!=ReservationStatus.RESERVED)return;Inventory x=repository.findByProductIdForUpdate(rr.getProductId()).orElseThrow();x.setAvailableQuantity(x.getAvailableQuantity()+rr.getQuantity());repository.save(x);rr.setStatus(ReservationStatus.RELEASED);reservations.save(rr);evict(rr.getProductId());}
@Transactional public void confirmReservation(String reservationId){
    InventoryReservation rr=reservations.findByReservationIdForUpdate(reservationId).orElseThrow();
    if(rr.getStatus()==ReservationStatus.CONFIRMED)return;
    if(rr.getStatus()!=ReservationStatus.RESERVED)throw new IllegalStateException("Reservation is no longer active: "+reservationId);
    if(rr.getExpiresAt().isBefore(Instant.now()))throw new IllegalStateException("Reservation expired: "+reservationId);
    rr.setStatus(ReservationStatus.CONFIRMED);
    reservations.save(rr);
}
@Scheduled(fixedDelayString="${inventory.reservation.expiry-check-ms:30000}") @Transactional public void expireReservations(){for(InventoryReservation candidate:reservations.findByStatusAndExpiresAtBefore(ReservationStatus.RESERVED,Instant.now())){
            InventoryReservation rr=reservations.findByReservationIdForUpdate(candidate.getReservationId()).orElse(null);
            if(rr==null || rr.getStatus()!=ReservationStatus.RESERVED || rr.getExpiresAt().isAfter(Instant.now())) continue;
            Inventory x=repository.findByProductIdForUpdate(rr.getProductId()).orElse(null);
            if(x==null) continue;
            x.setAvailableQuantity(x.getAvailableQuantity()+rr.getQuantity());
            repository.save(x);
            rr.setStatus(ReservationStatus.EXPIRED);
            reservations.save(rr);
            evict(rr.getProductId());
        }} private void evict(Long id){redis.delete(PREFIX+id);}}
